11	/**
12	 * An invoice raised against a {@link Project}: a monetary amount and the id of the project it
13	 * belongs to. Persisted to the {@code invoices} table (Flyway V4).
14	 */
15	@Entity
16	@Table(name = "invoices")
17	public class Invoice {
18	
19	    @Id
20	    @GeneratedValue(strategy = GenerationType.IDENTITY)
21	    private Long id;
22	
23	    @Column(name = "project_id")
24	    private Long projectId;
25	
26	    private BigDecimal amount;
27	
28	    /** Lifecycle stage: 'DRAFT' (the default for a new invoice), then 'SENT', then 'PAID'. */
